const ChapterTitle = ({item}) => {
  const frame = useCurrentFrame();
  const {fps, durationInFrames} = useVideoConfig();

  const props = item.props || {};
  const numberText = props.numberText;
  const titleLine1 = props.titleLine1;
  const titleLine2 = props.titleLine2;
  const accentColor = props.accentColor;
  const textColor = props.textColor;
  const bgColor = props.bgColor;
  const fontFamily = props.fontFamily;
  const transparentBackground = props.transparentBackground;

  const DESIGN_WIDTH = 1920;
  const DESIGN_HEIGHT = 1080;
  const scale = Math.min((item?.width || DESIGN_WIDTH) / DESIGN_WIDTH, (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT);

  const easeOutCubic = Easing.out(Easing.cubic);

  // Icon animation: duration 18f, delay 3f
  const iconScale = interpolate(frame, [3, 21], [0.6, 1], {
    easing: easeOutCubic,
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp'
  });
  const iconOpacity = interpolate(frame, [3, 21], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp'
  });

  // Line 1 animation: duration 16f, delay 14f
  const line1X = interpolate(frame, [14, 30], [-30, 0], {
    easing: easeOutCubic,
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp'
  });
  const line1Opacity = interpolate(frame, [14, 30], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp'
  });

  // Line 2 animation: duration 16f, delay 22f
  const line2X = interpolate(frame, [22, 38], [-30, 0], {
    easing: easeOutCubic,
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp'
  });
  const line2Opacity = interpolate(frame, [22, 38], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp'
  });

  const rootStyle = {
    position: 'absolute',
    top: 0,
    left: 0,
    width: DESIGN_WIDTH,
    height: DESIGN_HEIGHT,
    transform: `scale(${scale})`,
    transformOrigin: 'top left',
    backgroundColor: transparentBackground ? 'transparent' : bgColor,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    fontFamily: fontFamily,
    overflow: 'hidden',
  };

  const contentStyle = {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
  };

  const iconBoxStyle = {
    width: 140,
    height: 140,
    backgroundColor: '#FFFFFF',
    borderRadius: 24,
    boxShadow: '0 4px 20px rgba(0,0,0,0.10)',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    transform: `scale(${iconScale})`,
    opacity: iconOpacity,
    flexShrink: 0,
  };

  const numberStyle = {
    color: accentColor,
    fontSize: 80,
    fontWeight: 900,
    margin: 0,
    lineHeight: 1,
  };

  const textContainerStyle = {
    display: 'flex',
    flexDirection: 'column',
    marginLeft: 40,
  };

  const textLineBaseStyle = {
    color: textColor,
    fontSize: 72,
    fontWeight: 900,
    lineHeight: 1.2,
    margin: 0,
    whiteSpace: 'nowrap',
  };

  return (
    <div style={rootStyle}>
      <div style={contentStyle}>
        <div style={iconBoxStyle}>
          <span style={numberStyle}>{numberText}</span>
        </div>
        <div style={textContainerStyle}>
          <div style={{ opacity: line1Opacity, transform: `translateX(${line1X}px)` }}>
            <h1 style={textLineBaseStyle}>{titleLine1}</h1>
          </div>
          <div style={{ opacity: line2Opacity, transform: `translateX(${line2X}px)` }}>
            <h1 style={textLineBaseStyle}>{titleLine2}</h1>
          </div>
        </div>
      </div>
    </div>
  );
};

const TimelineAnimation = ({ item }) => {
  const frame = useCurrentFrame();
  const { width, height } = item;
  const DESIGN_WIDTH = 1920;
  const DESIGN_HEIGHT = 1080;
  const scale = Math.min(
    (width || DESIGN_WIDTH) / DESIGN_WIDTH,
    (height || DESIGN_HEIGHT) / DESIGN_HEIGHT
  );

  const props = item.props || {};
  const text1 = props.text1;
  const text2 = props.text2;
  const text3line1 = props.text3line1;
  const text3line2 = props.text3line2;
  const dotColor = props.dotColor;
  const textColor = props.textColor;
  const transparentBackground = props.transparentBackground === 'true' || props.transparentBackground === true;
  const fontFamily = props.fontFamily;

  const easeOut = Easing.out(Easing.cubic);

  const dot1Opacity = interpolate(frame, [0, 30], [0, 1], { extrapolateRight: 'clamp', easing: easeOut });
  const dot1Blur = interpolate(frame, [0, 30], [12, 0], { extrapolateRight: 'clamp', easing: easeOut });
  const text1Opacity = interpolate(frame, [8, 33], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });
  const text1Y = interpolate(frame, [8, 33], [20, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });
  const line1Scale = interpolate(frame, [35, 60], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });

  const dot2Opacity = interpolate(frame, [60, 90], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });
  const dot2Blur = interpolate(frame, [60, 90], [12, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });
  const text2Opacity = interpolate(frame, [68, 93], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });
  const text2Y = interpolate(frame, [68, 93], [20, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });
  const line2Scale = interpolate(frame, [95, 120], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });

  const dot3Opacity = interpolate(frame, [120, 150], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });
  const dot3Blur = interpolate(frame, [120, 150], [12, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });
  const text3Opacity = interpolate(frame, [128, 153], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });
  const text3Y = interpolate(frame, [128, 153], [20, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });

  const DOT_R = 12;
  const SPACING = 160;
  const TEXT_LEFT = 56;
  const FONT_SIZE = 52;
  const LINE_HEIGHT = 1.3;

  // dot center Y coords (relative to container)
  const cy1 = 0;
  const cy2 = SPACING;
  const cy3 = SPACING * 2;

  const dotEl = (cy, opacity, blur) => (
    <div style={{
      position: 'absolute',
      left: -DOT_R,
      top: cy - DOT_R,
      width: DOT_R * 2,
      height: DOT_R * 2,
      borderRadius: DOT_R,
      backgroundColor: dotColor,
      boxShadow: '0 0 10px rgba(255,255,255,0.7)',
      opacity,
      filter: `blur(${blur}px)`
    }} />
  );

  const lineEl = (cy, scaleY) => (
    <div style={{
      position: 'absolute',
      left: -1.5,
      top: cy + DOT_R,
      width: 3,
      height: SPACING - DOT_R * 2,
      backgroundColor: dotColor,
      borderRadius: 1.5,
      transformOrigin: 'top center',
      transform: `scaleY(${scaleY})`
    }} />
  );

  // text anchored to dot center: top = cy - half of single line height
  const singleLineH = FONT_SIZE * LINE_HEIGHT;
  const textEl = (cy, lines, opacity, ty) => (
    <div style={{
      position: 'absolute',
      left: TEXT_LEFT,
      top: cy - singleLineH / 2,
      opacity,
      transform: `translateY(${ty}px)`,
      fontSize: FONT_SIZE,
      fontWeight: 700,
      lineHeight: LINE_HEIGHT,
      color: textColor,
      whiteSpace: 'pre',
      pointerEvents: 'none'
    }}>
      {lines}
    </div>
  );

  return (
    <div style={{
      position: 'absolute', top: 0, left: 0,
      width: DESIGN_WIDTH, height: DESIGN_HEIGHT,
      transform: `scale(${scale})`, transformOrigin: 'top left',
      backgroundColor: transparentBackground ? 'transparent' : '#000000',
      fontFamily
    }}>
      <div style={{ position: 'absolute', left: 180, top: 380 }}>
        {dotEl(cy1, dot1Opacity, dot1Blur)}
        {textEl(cy1, text1, text1Opacity, text1Y)}
        {lineEl(cy1, line1Scale)}

        {dotEl(cy2, dot2Opacity, dot2Blur)}
        {textEl(cy2, text2, text2Opacity, text2Y)}
        {lineEl(cy2, line2Scale)}

        {dotEl(cy3, dot3Opacity, dot3Blur)}
        {textEl(cy3, <>{text3line1}<br />{text3line2}</>, text3Opacity, text3Y)}
      </div>
    </div>
  );
};

const PieChartOverlay = ({item}) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();

  const props = item.props || {};
  const label1 = props.label1;
  const label2 = props.label2;
  const color1 = props.color1;
  const color2 = props.color2;
  const bgColor = props.bgColor;
  const textColor = props.textColor;

  const DESIGN_WIDTH = 1920;
  const DESIGN_HEIGHT = 1080;
  const scale = Math.min((item?.width || DESIGN_WIDTH) / DESIGN_WIDTH, (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT);

  // Phase 1: 白色圆盘从中心弹出 (0~20帧)
  const discScale = spring({ frame, fps, config: { damping: 10, stiffness: 160, mass: 0.8 } });

  // Phase 2: 橙色扇区 0→25% (30~55帧)
  const phase2Progress = interpolate(frame, [30, 55], [0, 1], {
    easing: Easing.out(Easing.cubic),
    extrapolateLeft: 'clamp', extrapolateRight: 'clamp'
  });

  // Phase 3: 橙色扇区 25%→50% (70~95帧)
  const phase3Progress = interpolate(frame, [70, 95], [0, 1], {
    easing: Easing.out(Easing.cubic),
    extrapolateLeft: 'clamp', extrapolateRight: 'clamp'
  });

  // 最终橙色扇区角度：0→180度
  const orangeDeg = (phase2Progress * 90) + (phase3Progress * 90);

  // 标注在最终状态后淡入
  const labelOpacity = interpolate(frame, [95, 110], [0, 1], {
    extrapolateLeft: 'clamp', extrapolateRight: 'clamp'
  });

  // 中心文字：初始显示 100% Emergency Fund，橙色出现后隐藏
  const centerTextOpacity = interpolate(frame, [20, 30], [1, 0], {
    extrapolateLeft: 'clamp', extrapolateRight: 'clamp'
  });

  const labelBaseStyle = {
    position: 'absolute',
    opacity: labelOpacity,
    fontFamily: 'Inter, system-ui, sans-serif',
    fontWeight: 800, fontSize: 34,
    color: textColor,
    whiteSpace: 'pre-line', textAlign: 'center', lineHeight: 1.25, width: 280,
  };

  // Use CSS conic-gradient instead of SVG arc path.
  // conic-gradient has no degeneracy at any angle (including 90°, 180°, 270°),
  // completely eliminating the SVG arc flip/flash bug.
  const pieStyle = {
    width: 360,
    height: 360,
    borderRadius: '50%',
    background: 'conic-gradient(from -90deg, ' + color1 + ' 0deg, ' + color1 + ' ' + orangeDeg + 'deg, ' + color2 + ' ' + orangeDeg + 'deg, ' + color2 + ' 360deg)',
    boxShadow: '0px 12px 32px rgba(0,0,0,0.18)',
    flexShrink: 0,
  };

  return (
    <div style={{
      position: 'absolute', top: 0, left: 0,
      width: DESIGN_WIDTH, height: DESIGN_HEIGHT,
      transform: 'scale(' + scale + ')', transformOrigin: 'top left',
      backgroundColor: '#ffffff',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
    }}>
      <div style={{
        width: 1140, height: 800,
        backgroundColor: bgColor, borderRadius: 40,
        display: 'flex', justifyContent: 'center', alignItems: 'center',
        boxShadow: '0 25px 50px -12px rgba(0,0,0,0.1)',
        position: 'relative',
      }}>
        <div style={{
          position: 'relative', width: 400, height: 400,
          transform: 'scale(' + discScale + ')',
          transformOrigin: 'center center',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}>
          <div style={pieStyle} />

          {/* 中心文字：100% Emergency Fund，橙色出现前显示 */}
          <div style={{
            position: 'absolute', top: 0, left: 0, width: 400, height: 400,
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            opacity: centerTextOpacity,
            pointerEvents: 'none',
          }}>
            <div style={{
              fontFamily: 'Inter, system-ui, sans-serif',
              fontWeight: 800, fontSize: 32,
              color: '#111', textAlign: 'center', lineHeight: 1.3,
            }}>100%{String.fromCharCode(10)}Emergency Fund</div>
          </div>

          {/* 外部标注 */}
          <div style={{ ...labelBaseStyle, left: 420, top: 20 }}>{label1}</div>
          <div style={{ ...labelBaseStyle, right: 420, bottom: 20 }}>{label2}</div>
        </div>
      </div>
    </div>
  );
};

const TitleCard = ({item}) => {
  const frame = useCurrentFrame();
  const { durationInFrames } = useVideoConfig();

  const props = item.props || {};
  const line1Text = props.line1Text;
  const line2Text = props.line2Text;
  const line3Text = props.line3Text;
  const line4aText = props.line4aText;
  const line4bText = props.line4bText;
  const accentColor = props.accentColor;
  const textColor = props.textColor;
  const fontFamily = props.fontFamily;

  const DESIGN_WIDTH = 800;
  const DESIGN_HEIGHT = 450;
  const scale = Math.min((item?.width || DESIGN_WIDTH) / DESIGN_WIDTH, (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT);

  const outroStart = Math.max(1, durationInFrames - 15);
  const outroEnd = Math.max(outroStart + 1, durationInFrames);

  const easeInQuad = (t) => t * t;
  const t = interpolate(frame, [outroStart, outroEnd], [0, 1], {
    extrapolateLeft: 'clamp', extrapolateRight: 'clamp'
  });
  const outTranslateX = easeInQuad(t) * -110;
  const speed = 2 * t;
  const blurAmount = speed * 4;
  const motionFilter = t > 0.02 ? 'blur(' + blurAmount + 'px)' : 'none';

  const dropShadow = '3px 4px 6px rgba(0,0,0,0.6)';

  const words1 = (line1Text || '').split(' ').filter(Boolean);
  const words2 = (line2Text || '').split(' ').filter(Boolean);
  const words3 = (line3Text || '').split(' ').filter(Boolean);
  const words4a = (line4aText || '').split(' ').filter(Boolean);
  const words4b = (line4bText || '').split(' ').filter(Boolean);

  const start2 = words1.length;
  const start3 = start2 + words2.length;
  const start4a = start3 + words3.length;
  const start4b = start4a + words4a.length;

  const INTRO_DELAY = 8;  // 开头延迟稍长
  const WORD_INTERVAL = 7; // 每词间隔7帧，更从容

  const renderWords = (wordsArray, fontSize, fontWeight, color, startIndex) => {
    return wordsArray.map((word, i) => {
      const delay = INTRO_DELAY + (startIndex + i) * WORD_INTERVAL;
      const visible = frame >= delay;
      return (
        <span key={startIndex + i} style={{
          visibility: visible ? 'visible' : 'hidden',
          fontSize, fontWeight, color,
          textShadow: dropShadow,
          lineHeight: 1.1,
          letterSpacing: fontSize === '90px' ? '-0.02em' : '-0.01em',
        }}>{word + '\u00A0'}</span>
      );
    });
  };

  return (
    <div style={{
      position: 'absolute', top: 0, left: 0,
      width: DESIGN_WIDTH, height: DESIGN_HEIGHT,
      transform: 'scale(' + scale + ')', transformOrigin: 'top left',
    }}>
      <div style={{
        transform: 'translateX(' + outTranslateX + '%)',
        filter: motionFilter,
        display: 'flex', flexDirection: 'column', alignItems: 'flex-start',
        padding: '30px', fontFamily,
        willChange: 'transform, filter',
      }}>
        <div style={{ lineHeight: 1.0 }}>{renderWords(words1, '90px', 900, accentColor, 0)}</div>
        <div style={{ lineHeight: 1.1, marginTop: '4px' }}>{renderWords(words2, '45px', 600, textColor, start2)}</div>
        <div style={{ lineHeight: 1.0, marginTop: '4px' }}>{renderWords(words3, '90px', 900, accentColor, start3)}</div>
        <div style={{ lineHeight: 1.0, marginTop: '4px', display: 'flex', alignItems: 'baseline' }}>
          {renderWords(words4a, '90px', 900, accentColor, start4a)}
          {renderWords(words4b, '45px', 600, textColor, start4b)}
        </div>
      </div>
    </div>
  );
};

const StaggeredQuestions = ({item}) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const props = item.props || {};

  const q1Text = props.q1Text;
  const q2Text = props.q2Text;
  const q3Text = props.q3Text;
  const q4Text = props.q4Text;
  const fontFamily = props.fontFamily;
  const textColor = props.textColor;
  const bgBaseColor = props.bgBaseColor;
  const bgAccent1 = props.bgAccent1;
  const bgAccent2 = props.bgAccent2;
  const animationSpeed = props.animationSpeed;
  const transparentBackground = props.transparentBackground;

  const DESIGN_WIDTH = 1920;
  const DESIGN_HEIGHT = 1080;
  const scale = Math.min((item?.width || DESIGN_WIDTH) / DESIGN_WIDTH, (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT);
  const safeFps = fps || 30;

  const sprConfig = { damping: 18, stiffness: 120 };
  const speed = Math.max(0.1, animationSpeed);
  const numberToFirstWord = Math.max(1, Math.round(6 / speed));
  const wordDelay = Math.max(1, Math.round(5 / speed));
  const interRowGap = Math.max(1, Math.round(12 / speed));

  const parseQuestion = (text) => {
    const match = text.match(/^(\d+\.)\s*([\s\S]*)/);
    if (match) return { number: match[1], words: match[2].replace(/\n/g, ' ').split(' ').filter(Boolean) };
    return { number: '', words: text.split(' ').filter(Boolean) };
  };

  const questions = [q1Text, q2Text, q3Text, q4Text];
  const parsed = questions.map(parseQuestion);

  const rowStarts = [];
  let cursor = 15;
  for (let i = 0; i < parsed.length; i++) {
    rowStarts.push(cursor);
    const lastWordOffset = numberToFirstWord + (parsed[i].words.length - 1) * wordDelay;
    cursor = cursor + lastWordOffset + interRowGap;
  }

  const rootStyle = {
    position: 'absolute',
    top: 0, left: 0,
    width: DESIGN_WIDTH, height: DESIGN_HEIGHT,
    transform: `scale(${scale})`,
    transformOrigin: 'top left',
    backgroundColor: transparentBackground ? 'transparent' : bgBaseColor,
    overflow: 'hidden',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
  };

  const textContainerStyle = {
    display: 'flex',
    flexDirection: 'column',
    width: '1000px',
    transform: 'translateX(80px)',
    zIndex: 10,
  };

  const sharedTextStyle = {
    fontFamily,
    fontSize: '60px',
    fontWeight: 800,
    color: textColor,
    lineHeight: 1.25,
    letterSpacing: '-0.02em',
    textShadow: '0px 4px 16px rgba(0,0,0,0.4)',
  };

  return (
    <div style={rootStyle}>
      {!transparentBackground && (
        <div style={{ position: 'absolute', width: '100%', height: '100%', top: 0, left: 0 }}>
          <div style={{ position: 'absolute', width: '100%', height: '100%', filter: 'blur(100px)' }}>
            <div style={{ position: 'absolute', top: '-20%', left: '-10%', width: '80%', height: '80%', backgroundColor: bgAccent1, borderRadius: '50%', opacity: 0.6 }} />
            <div style={{ position: 'absolute', top: '40%', right: '-20%', width: '70%', height: '90%', backgroundColor: bgAccent2, borderRadius: '50%', opacity: 0.6 }} />
            <div style={{ position: 'absolute', top: '10%', left: '40%', width: '60%', height: '60%', backgroundColor: bgAccent1, borderRadius: '50%', opacity: 0.4 }} />
          </div>
        </div>
      )}

      <div style={textContainerStyle}>
        {parsed.map(({ number, words }, qi) => {
          const rowStart = rowStarts[qi];

          const numSpr = spring({ frame: Math.max(0, frame - rowStart), fps: safeFps, config: sprConfig });
          const numOpacity = Math.min(1, Math.max(0, numSpr));
          const numTx = interpolate(numSpr, [0, 1], [-28, 0]);

          return (
            <div key={qi} style={{
              ...sharedTextStyle,
              display: 'flex',
              flexDirection: 'row',
              alignItems: 'flex-start',
              marginBottom: '35px',
            }}>
              {/* Number column — fixed width so words always start at same X */}
              <span style={{
                display: 'inline-block',
                flexShrink: 0,
                width: '90px',
                opacity: numOpacity,
                transform: `translateX(${numTx}px)`,
              }}>
                {number}
              </span>
              {/* Words column — wraps internally, second line aligns with first word */}
              <div style={{
                display: 'flex',
                flexWrap: 'wrap',
                alignItems: 'baseline',
                columnGap: '0.3em',
                rowGap: '0.1em',
                flex: 1,
              }}>
                {words.map((word, wi) => {
                  const wordStart = rowStart + numberToFirstWord + wi * wordDelay;
                  const wSpr = spring({ frame: Math.max(0, frame - wordStart), fps: safeFps, config: sprConfig });
                  const wOpacity = Math.min(1, Math.max(0, wSpr));
                  const wTx = interpolate(wSpr, [0, 1], [30, 0]);
                  return (
                    <span key={wi} style={{
                      display: 'inline-block',
                      opacity: wOpacity,
                      transform: `translateX(${wTx}px)`,
                    }}>
                      {word}
                    </span>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

const QuoteCard = ({item}) => {
  const frame = useCurrentFrame();
  const { durationInFrames } = useVideoConfig();

  const props = item.props || {};
  const quoteText = props.quoteText;
  const quoteColor = props.quoteColor;
  const textColor = props.textColor;
  const fontFamily = props.fontFamily;
  const transparentBackground = props.transparentBackground;

  // 扩大内部画布，给光效留出血区
  const DESIGN_WIDTH = 1060;
  const DESIGN_HEIGHT = 680;

  const hexToRgb = (hex) => {
    const h = (hex || '#ffffff').replace('#', '');
    const r = parseInt(h.substring(0,2), 16);
    const g = parseInt(h.substring(2,4), 16);
    const b = parseInt(h.substring(4,6), 16);
    return {r, g, b};
  };

  const qc = hexToRgb(quoteColor);
  const tc = hexToRgb(textColor);

  const masterAlpha = interpolate(frame, [0, 25], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  const textAlpha = interpolate(frame, [12, 32], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  const cardY = interpolate(frame, [0, 28], [24, 0], {
    extrapolateRight: 'clamp',
    easing: Easing.out(Easing.cubic),
  });

  const fadeOutStart = durationInFrames > 18 ? durationInFrames - 18 : 0;
  const exitAlpha = interpolate(frame, [fadeOutStart, durationInFrames], [1, 0], {
    extrapolate: 'clamp',
  });
  const exitY = interpolate(frame, [fadeOutStart, durationInFrames], [0, 24], {
    extrapolate: 'clamp',
    easing: Easing.in(Easing.cubic),
  });

  const isExiting = frame >= fadeOutStart;
  const finalAlpha = masterAlpha * exitAlpha;
  const finalTextAlpha = textAlpha * exitAlpha;
